user_prompt:
method rolling_max(numbers: seq<int>) returns (result: seq<int>)
    requires |numbers| > 0
    ensures |result| == |numbers| 
    ensures forall i :: 0 <= i < |result| ==> result[i] == Max(numbers[0..i+1])
{
    var max_so_far := numbers[0];
    var n := |numbers|;
    result := new int[n];

    result[0] := numbers[0];

    var i := 1;
    while i < n
        invariant 0 < i <= n
        invariant |result| == n
        invariant result[0..i] == [numbers[0]] + [max_so_far] * (i - 1)
    {
        if numbers[i] > max_so_far {
            max_so_far := numbers[i];
        }
        result[i] := max_so_far;
        i := i + 1;
    }
}

problem_data.canonical_solution:
running_max = None
result = []

for n in numbers:
    if running_max is None:
        running_max = n
    else:
        running_max = max(running_max, n)

    result.append(running_max)

return result

